-- Surveys and feedback; hostel setup, rooms, beds, allocation, attendance and mess.
CREATE TABLE public.surveys (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, audience VARCHAR(20) NOT NULL CHECK (audience IN ('Students', 'Parents', 'Staff', 'Students and parents')), opens_on DATE NOT NULL, closes_on DATE NOT NULL, anonymous BOOLEAN NOT NULL DEFAULT false, scheduled BOOLEAN NOT NULL DEFAULT false, kind VARCHAR(16) NOT NULL DEFAULT 'Survey' CHECK (kind IN ('Survey', 'Teacher feedback')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (closes_on >= opens_on));
CREATE TABLE public.survey_questions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), survey_id UUID NOT NULL REFERENCES public.surveys(id) ON DELETE CASCADE, position INTEGER NOT NULL, text VARCHAR(200) NOT NULL, kind VARCHAR(16) NOT NULL CHECK (kind IN ('Rating 1 – 5', 'Multiple choice', 'Written answer')), options VARCHAR(300) NOT NULL DEFAULT '');
CREATE TABLE public.survey_responses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), survey_id UUID NOT NULL REFERENCES public.surveys(id) ON DELETE CASCADE, group_label VARCHAR(40) NOT NULL DEFAULT '', teacher_name VARCHAR(80) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.survey_answers (response_id UUID NOT NULL REFERENCES public.survey_responses(id) ON DELETE CASCADE, question_id UUID NOT NULL REFERENCES public.survey_questions(id) ON DELETE CASCADE, rating SMALLINT CHECK (rating BETWEEN 1 AND 5), choice VARCHAR(80), answer_text VARCHAR(1000), PRIMARY KEY (response_id, question_id));

CREATE TABLE public.hostels (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, warden VARCHAR(80) NOT NULL DEFAULT '', status VARCHAR(8) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')), UNIQUE (institution_id, name));
CREATE TABLE public.hostel_buildings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, hostel_id UUID NOT NULL REFERENCES public.hostels(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, use_label VARCHAR(80) NOT NULL);
CREATE TABLE public.hostel_floors (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, building_id UUID NOT NULL REFERENCES public.hostel_buildings(id) ON DELETE CASCADE, name VARCHAR(20) NOT NULL, sort INTEGER NOT NULL);
CREATE TABLE public.hostel_rooms (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, hostel_id UUID NOT NULL REFERENCES public.hostels(id) ON DELETE CASCADE, building_id UUID NOT NULL REFERENCES public.hostel_buildings(id) ON DELETE CASCADE, floor_id UUID NOT NULL REFERENCES public.hostel_floors(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL, room_type VARCHAR(30) NOT NULL, beds INTEGER NOT NULL CHECK (beds > 0), maintenance BOOLEAN NOT NULL DEFAULT false, UNIQUE (hostel_id, code));
CREATE TABLE public.hostel_beds (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, room_id UUID NOT NULL REFERENCES public.hostel_rooms(id) ON DELETE CASCADE, label VARCHAR(20) NOT NULL, seq INTEGER NOT NULL);
CREATE TABLE public.hostel_room_types (institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(30) NOT NULL, fee_per_year INTEGER, for_classes VARCHAR(40) NOT NULL DEFAULT '', PRIMARY KEY (institution_id, name));
CREATE TABLE public.hostel_meal_plans (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(40) NOT NULL, meals VARCHAR(80) NOT NULL DEFAULT 'Breakfast, lunch, snacks, dinner', per_month INTEGER, status VARCHAR(8) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')), UNIQUE (institution_id, name));
CREATE TABLE public.hostel_allocations (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, bed_id UUID NOT NULL REFERENCES public.hostel_beds(id) ON DELETE CASCADE, from_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(18) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'On home leave', 'Transfer requested', 'Vacated')), transfer_bed_id UUID REFERENCES public.hostel_beds(id) ON DELETE SET NULL, meal_plan_id UUID REFERENCES public.hostel_meal_plans(id) ON DELETE SET NULL);
CREATE UNIQUE INDEX hostel_alloc_bed ON public.hostel_allocations (bed_id) WHERE status <> 'Vacated';
CREATE UNIQUE INDEX hostel_alloc_student ON public.hostel_allocations (student_id) WHERE status <> 'Vacated';
CREATE TABLE public.hostel_attendance (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, att_date DATE NOT NULL DEFAULT CURRENT_DATE, kind VARCHAR(16) NOT NULL CHECK (kind IN ('Night roll call', 'Home leave', 'Outing')), out_time VARCHAR(5), in_time VARCHAR(5), reason VARCHAR(80) NOT NULL DEFAULT '', status VARCHAR(10) NOT NULL DEFAULT 'Present' CHECK (status IN ('Present', 'Out', 'Returned')));
CREATE TABLE public.hostel_menu (institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, day INTEGER NOT NULL CHECK (day BETWEEN 0 AND 6), breakfast VARCHAR(80) NOT NULL DEFAULT '', lunch VARCHAR(80) NOT NULL DEFAULT '', snacks VARCHAR(80) NOT NULL DEFAULT '', dinner VARCHAR(80) NOT NULL DEFAULT '', PRIMARY KEY (institution_id, day));
CREATE TABLE public.mess_day_students (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, meals VARCHAR(16) NOT NULL CHECK (meals IN ('Lunch', 'Lunch + snacks')), diet VARCHAR(10) NOT NULL CHECK (diet IN ('Veg', 'Non-veg', 'Jain')), since DATE NOT NULL DEFAULT CURRENT_DATE, per_month INTEGER, allergy VARCHAR(40) NOT NULL DEFAULT '', opted BOOLEAN NOT NULL DEFAULT true, UNIQUE (student_id));
CREATE TABLE public.mess_requests (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, meals VARCHAR(16) NOT NULL, diet VARCHAR(10) NOT NULL, requested_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(8) NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'Approved', 'Declined')));
ALTER TABLE public.surveys ENABLE ROW LEVEL SECURITY; ALTER TABLE public.survey_questions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.survey_responses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.survey_answers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hostels ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_buildings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_floors ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_rooms ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_beds ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_room_types ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_meal_plans ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_allocations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_attendance ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hostel_menu ENABLE ROW LEVEL SECURITY; ALTER TABLE public.mess_day_students ENABLE ROW LEVEL SECURITY; ALTER TABLE public.mess_requests ENABLE ROW LEVEL SECURITY;
